from pathlib import Path
p=Path('personalizza.html')
s=p.read_text()
old='''<style id="hamburgeria-layout-v3">.pagina{background-size:cover!important;background-position:center center!important;background-repeat:no-repeat!important;background-color:#21140d!important}.pagina:before{backdrop-filter:none!important;-webkit-backdrop-filter:none!important;background:rgba(0,0,0,.12)!important}.logo,.logo-wrap,.logo-box,.logo-container{background:transparent!important;box-shadow:none!important;backdrop-filter:none!important;-webkit-backdrop-filter:none!important;border:none!important;filter:none!important}.logo{padding:0!important;border-radius:0!important}.logo-wrap:before,.logo-wrap:after,.logo-box:before,.logo-box:after,.logo-container:before,.logo-container:after{display:none!important}@media(max-width:640px){.pagina{background-size:100% auto!important;background-position:center center!important;background-repeat:repeat-y!important}}</style>'''
new='''<style id="hamburgeria-layout-final">body{background-image:linear-gradient(rgba(0,0,0,.10),rgba(0,0,0,.10)),url("${backgroundDataUrl}")!important;background-size:auto 100%!important;background-position:center center!important;background-repeat:no-repeat!important;background-attachment:fixed!important;background-color:#21140d!important}.pagina{background:transparent!important}.logo,.logo-wrap,.logo-box,.logo-container{background:transparent!important;box-shadow:none!important;backdrop-filter:none!important;-webkit-backdrop-filter:none!important;border:none!important;filter:none!important}.logo{padding:0!important;border-radius:0!important}.logo-wrap:before,.logo-wrap:after,.logo-box:before,.logo-box:after,.logo-container:before,.logo-container:after{display:none!important}@media(min-width:700px){body{background-size:cover!important}}</style>'''
if old not in s: raise SystemExit('hamburgeria v3 anchor missing')
s=s.replace(old,new,1)
p.write_text(s)
